// We can infer NOT NULL predicates on arguments of an AND expression
{"a > b and c = d", new String[] {"a", "b", "c", "d"}},
{"a IS NULL and b > c", new String[] {"b", "c"}},
// We cannot infer NOT NULL predicates on arguments of an OR expression
