private static int skewedSample(Random rnd, int max) {
    double uniform = rnd.nextDouble();
    double var = Math.pow(uniform, 8.0);
    double pareto = 0.2 / var;

    int val = (int) pareto;
    return val > max ? val % max : val;
}

