assertEquals("\\string", exec("'\\\\string'"));
// `\"` is a `"` if surrounded by `"`s
assertEquals("\"string", exec("\"\\\"string\""));
Exception e = expectScriptThrows(IllegalArgumentException.class, () -> exec("'\\\"string'", false));
